"""Factor exact, explicitly recognized scalar mesh guards into shared groups.

Each match checks every input, output and calculation property against the
existing builder's complete guard expression. Geometry is the only wildcard.
Different call sites retain their own geometry and Repeat-zone context. The
original expression is removed only when normal compaction proves it unused.
No acceptance threshold or arithmetic expression is simplified.
"""
import bpy

from .path_surface_nodes import _Nodes
from . import boundary_quad_bridge_nodes as bridge
from . import bundle_median_closure_nodes as closure
from .field_compaction import constant

PREFIX = 'Prochitecture Streets / Shared exact mesh guard / '
# These are the only built-ins emitted by the two reviewed guard builders.
PROPERTIES = {
    'GeometryNodeInputIndex': (), 'GeometryNodeInputPosition': (),
    'GeometryNodeOffsetCornerInFace': (), 'GeometryNodeVertexOfCorner': (),
    'GeometryNodeSampleIndex': ('data_type', 'domain', 'clamp'),
    'ShaderNodeVectorMath': ('operation',), 'ShaderNodeSeparateXYZ': (),
    'GeometryNodeAttributeDomainSize': ('component',),
    'GeometryNodeAttributeStatistic': ('data_type', 'domain'),
    'FunctionNodeCompare': ('data_type', 'operation', 'mode'),
    'FunctionNodeBooleanMath': ('operation',),
    'GeometryNodeEdgesOfCorner': (), 'GeometryNodeInputMeshEdgeVertices': (),
    'GeometryNodeSwitch': ('input_type',),
    'GeometryNodeAccumulateField': ('data_type', 'domain'),
    'GeometryNodeInputMeshEdgeNeighbors': (),
}


def build(kind):
    if kind not in ('positive', 'oriented'):
        raise ValueError('Unknown mesh guard')
    name = PREFIX+kind+' v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    tree = bpy.data.node_groups.new(name, 'GeometryNodeTree'); g = _Nodes(tree)
    tree.interface.new_socket(name='Geometry', in_out='INPUT', socket_type='NodeSocketGeometry')
    inp = g.node('NodeGroupInput', 'Caller mesh')
    result = (bridge._mesh_good(g, inp.outputs['Geometry']) if kind == 'positive'
              else closure._oriented_seams(g, inp.outputs['Geometry']))
    tree.interface.new_socket(name='Value', in_out='OUTPUT',
        socket_type='NodeSocketBool' if result.type == 'BOOLEAN' else 'NodeSocketFloat')
    out = g.node('NodeGroupOutput', 'Unchanged guard result'); g.set(result, out.inputs['Value'])
    for node in tree.nodes:
        if node.type not in ('GROUP_INPUT', 'GROUP_OUTPUT') and node.bl_idname not in PROPERTIES:
            raise ValueError(('Guard builder changed; review its calculation properties', node.bl_idname))
    tree['st_shared_exact_mesh_guard'] = 1
    return tree


class Pattern:
    def __init__(self, tree):
        self.tree = tree
        self.input_links = {l.to_socket: l.from_socket for l in tree.links}
        output = next(n for n in tree.nodes if n.type == 'GROUP_OUTPUT')
        self.root = self.input_links[output.inputs['Value']]

    def match(self, root, incoming):
        geometry = None; found = set(); checked = set()

        def pair(pattern, actual):
            nonlocal geometry
            if pattern.node.type == 'GROUP_INPUT':
                if pattern.name != 'Geometry' or actual.type != 'GEOMETRY': return False
                if geometry is not None and geometry != actual: return False
                geometry = actual; return True
            key = (pattern, actual)
            if key in checked: return True
            a, b = pattern.node, actual.node
            if a.bl_idname != b.bl_idname or b.mute or pattern.identifier != actual.identifier:
                return False
            if a.bl_idname not in PROPERTIES: return False
            if any(getattr(a, prop) != getattr(b, prop) for prop in PROPERTIES[a.bl_idname]):
                return False
            if len(a.inputs) != len(b.inputs): return False
            checked.add(key)
            for x, y in zip(a.inputs, b.inputs):
                if x.identifier != y.identifier or x.bl_idname != y.bl_idname: return False
                original = self.input_links.get(x); links = incoming.get(y, ())
                if original is not None:
                    if len(links) != 1 or not pair(original, links[0].from_socket): return False
                elif links or constant(getattr(x, 'default_value', None)) != constant(getattr(y, 'default_value', None)):
                    return False
            found.add(b); return True

        return (geometry, found) if pair(self.root, root) and geometry is not None else None


def reachable(roots):
    seen = set(); pending = list(roots)
    while pending:
        tree = pending.pop()
        if tree in seen: continue
        seen.add(tree)
        pending.extend(n.node_tree for n in tree.nodes if n.type == 'GROUP' and n.node_tree)
    return seen


def factor(roots, *, apply=False):
    """Recognize both guards; optionally rewire only their matched result sockets."""
    groups = reachable(roots)
    patterns = {kind: Pattern(build(kind)) for kind in ('positive', 'oriented')}
    rows = []
    for tree in sorted(groups, key=lambda t: t.name):
        if tree.name.startswith(PREFIX) or tree.animation_data:
            continue
        links = list(tree.links); incoming = {}; outgoing = {}
        if any(l.is_muted or not l.is_valid for l in links): continue
        for link in links:
            incoming.setdefault(link.to_socket, []).append(link)
            outgoing.setdefault(link.from_socket, []).append(link)
        matches = []
        for kind, pattern in patterns.items():
            for node in list(tree.nodes):
                if node.bl_idname != pattern.root.node.bl_idname: continue
                socket = node.outputs.get(pattern.root.identifier)
                if socket is None or not outgoing.get(socket): continue
                match = pattern.match(socket, incoming)
                if match is None: continue
                geometry, nodes = match
                targets = [l.to_socket for l in outgoing[socket]]
                # Never rewrite an order-dependent multi-input link.
                if any(t.is_multi_input for t in targets): continue
                matches.append((kind, pattern, node, socket, geometry, nodes, targets))
        for kind, pattern, node, socket, geometry, nodes, targets in matches:
            rows.append(dict(tree=tree.name, kind=kind, output_node=node.name,
                             matched_nodes=len(nodes), consumers=len(targets)))
            if apply:
                call = tree.nodes.new('GeometryNodeGroup'); call.node_tree = pattern.tree
                call.label = 'Exact shared '+kind+' mesh guard'
                tree.links.new(geometry, call.inputs['Geometry'])
                for target in targets:
                    tree.links.new(call.outputs['Value'], target, verify_limits=True)
    return rows
